wc -c analyse_image/test_model.ipynb; python3 - <<'EOF'
import json
for f in ['apprentissage/partie3_entrainement.ipynb','apprentissage/partie3_predictions.ipynb','analyse_image/classification.ipynb','analyse_image/test_model.ipynb']:
    try:
        nb=json.load(open(f))
    except Exception as e:
        print('='*20,f,'ERROR',e); continue
    print('='*30,f)
    for i,c in enumerate(nb['cells']):
        if c['cell_type']=='code':
            print(f'--- cell {i} ---')
            print(''.join(c['source'])[:1500])
EOF

